from pathlib import Path
import re,json,html
root=Path(__file__).resolve().parents[2];d=json.loads((root/'survey/anc/survey_snapshot.json').read_text());meta=json.loads((root/'survey/anc/release_metadata.json').read_text());old=(root/'HBC_Survey.html').read_text();nav=re.search(r'<nav class="navbar.*?</nav>',old,re.S).group();footer=re.search(r'<footer class="site-footer">.*?</footer>',old,re.S).group();shared=re.search(r'<!-- Shared site assets.*?<!-- /Shared site assets -->',old,re.S).group()
css='''
.survey{max-width:1200px;margin:auto;padding:0 24px 50px;color:#212529}.survey-hero{text-align:center;padding:38px 8px 24px}.survey-hero h1{font-size:2.3rem;line-height:1.3;font-weight:600;max-width:1050px;margin:0 auto 18px}.survey-hero .edition{color:#b32222;font-weight:600}.survey-hero p{margin:8px 0}.survey a{color:#0056b3}.survey .totals{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid #dee2e6;border-bottom:1px solid #dee2e6;margin:16px 0 24px;padding:16px 0}.survey .total{text-align:center}.survey .total strong{display:block;font-size:2rem;color:#18171c}.survey .total span{font-size:.85rem;color:#606775}.survey h2{font-size:1.16rem;background:#0056b3;color:white;padding:12px 16px;margin:28px 0 16px;font-weight:600}.survey .tools{display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin:14px 0}.survey label{font-size:.8rem;display:flex;flex-direction:column;gap:5px;margin:0}.survey input,.survey select,.survey button,.survey .download{border:1px solid #b5c0cc;border-radius:4px;padding:8px 11px;background:white;color:#212529;font:inherit;font-size:.85rem}.survey button,.survey .download{cursor:pointer;color:#0056b3;display:inline-block}.survey button:hover,.survey .download:hover{background:#eef4fb}.survey button:disabled{opacity:.4;cursor:default}.survey input{min-width:270px}.survey .plot{border:1px solid #e0e4e9;border-radius:5px;padding:8px;min-height:310px}.survey svg{width:100%;height:auto;display:block}.survey .plot circle{cursor:pointer}.survey .plot circle:hover,.survey .plot circle:focus{r:7;stroke:#18171c;stroke-width:2}.survey .muted{color:#66707d;font-size:.8rem}.survey .citation{border-left:3px solid #c52214;background:#f6f8fa;padding:14px 18px;font-size:.9rem}.survey .paper{border-bottom:1px solid #e5e8ec;padding:7px 0;font-size:.79rem;line-height:1.45}.survey .paper summary{cursor:pointer;display:block}.survey .paper .ref{color:#b32222;font-weight:600;display:inline-block;min-width:44px}.survey .paper .paper-title{font-weight:500;color:#171b21}.survey .paper .meta{color:#59626f;margin-left:44px;font-size:.73rem}.survey .paper .doi{overflow-wrap:anywhere}.survey .paper .detail{margin:6px 0 6px 44px;padding:10px 14px;background:#f4f7fb;overflow-wrap:anywhere}.survey .pager{display:flex;gap:14px;align-items:center;justify-content:space-between;margin:12px 0}.survey .notes{font-size:.85rem;line-height:1.65}.survey .history{width:100%;font-size:.83rem;border-collapse:collapse}.survey .history th,.survey .history td{text-align:left;padding:10px;vertical-align:top;border-bottom:1px solid #e0e4e9}.survey .history th{width:150px;color:#b32222}.survey .chart-pick{font-size:.82rem;background:#f6f8fa;padding:12px;min-height:46px}.survey .history-wrap{margin-top:24px}.survey :focus-visible{outline:3px solid #d64d38;outline-offset:2px}@media(max-width:700px){.survey{padding:0 14px 45px}.survey-hero h1{font-size:1.65rem}.survey .totals{grid-template-columns:repeat(2,1fr);gap:16px}.survey input{min-width:0;width:100%}.survey .tools label{flex:1;min-width:130px}.survey .tools label:first-child{flex-basis:100%}.survey .paper .meta{margin-left:0}.survey .paper .detail{margin-left:0}.survey .history th{width:100px}.survey .plot{min-height:150px}.survey-hero{padding-top:25px}}@media print{nav,footer,.tools,.pager{display:none!important}.survey .paper{break-inside:avoid}.survey h2{color:#0056b3;background:white}.survey{max-width:none}}
'''
counts=d['stats']['allByCategory'];N=len(d['records']);esc=html.escape
body=f'''<main class="survey"><header class="survey-hero"><div class="edition">v3.11 · 13 November 2026</div><h1>{esc(meta['title'])}</h1><p>Shreyas Sen · Purdue University</p><p class="muted">A searchable catalogue of HBC research and measured integrated-circuit progress.</p></header>
<div class="totals"><div class="total"><strong>{N}</strong><span>Total references</span></div><div class="total"><strong>{counts['ICs']}</strong><span>Integrated circuits</span></div><div class="total"><strong>{counts['Channels & models']}</strong><span>Channels and models</span></div><div class="total"><strong>{counts['Other literature']}</strong><span>Other literature</span></div></div>
<div class="tools"><a class="download" href="survey/HBC_Survey.xlsx" download>Excel workbook</a><a class="download" href="survey/HBC_Catalogue.pdf" download>Catalogue PDF</a><button id="csv">CSV bibliography</button><button id="bib">BibTeX</button><a class="download" href="survey/HBC_Catalogue_Overleaf.zip" download>Overleaf source</a></div>
<h2>Integrated-circuit energy efficiency · 2006–2026</h2>
<div class="tools"><label>Energy scope<select id="scope"><option value="S">Transmitter (TX)</option><option value="T" selected>Receiver (RX)</option><option value="U">Combined TX + RX</option></select></label><label>IC modality<select id="plotmode"><option value="">All IC modalities</option></select></label><button id="plotcsv">Download plotted data</button></div>
<div id="plot" class="plot"></div><div id="pick" class="chart-pick">Select a point to inspect its paper and measurement notes.</div>
<p class="muted">Only eligible fabricated custom solid-state IC records enter these comparisons. TX, RX, and combined energy are separate scopes; front-end-only and energy-per-sample values are not substituted for complete-receiver or per-bit energy. Logarithmic energy axis. Blank values are omitted. Conference and journal papers may describe the same chip. Adjacent implant modalities and inherited measurements remain identified in the record notes.</p>
<h2>Cite this survey</h2><div class="citation">Shreyas Sen, “{esc(meta['title'])},” v3.11, 13 November 2026. <a href="https://engineering.purdue.edu/~shreyas/SparcLab/HBC_Survey.html">SparcLab HBC Survey</a>.<br><small>Please cite each original paper for its technical results.</small></div>
<h2>Browse all {N} references</h2><div class="tools"><label>Search title, author, DOI, or reference number<input id="search" type="search" placeholder="e.g. implant, MAPCON, 339" /></label><label>Collection<select id="category"><option value="">All references</option><option>ICs</option><option>Channels &amp; models</option><option>Other literature</option></select></label><label>Year<select id="year"><option value="">All years</option></select></label></div>
<div class="pager"><span id="resultcount" class="muted" aria-live="polite"></span><span><button id="prev">Previous</button> <button id="next">Next</button></span></div><div id="papers"></div><div class="pager"><span id="pagecount" class="muted"></span><button id="toplist">Back to filters</button></div>
<details class="history-wrap"><summary>Version history</summary><table class="history"><tr><th>V1<br>19 June 2022</th><td>RFIC invited talk — “Secure and Efficient Internet of Bodies (IoB) using Body as a ‘Wire’.” Human Body Communications workshop.</td></tr><tr><th>V2<br>23 February 2023</th><td>ISSCC Forum 7 invited talk — “Secure and Efficient Internet of Bodies (IoB) using Body as a ‘Wire’.” Advanced Circuits and Technologies for Wearable and Implantable Devices.</td></tr><tr><th>v3.10<br>October 2026</th><td>Expanded literature catalogue, IC-only energy plots, compact paper list, AI and conflict-of-interest statements.</td></tr><tr><th>v3.11<br>13 November 2026</th><td>Literature search and verified backfills, updated catalogue and downloadable files. Month-based version suffix: .11 denotes November.</td></tr></table></details>
<h2>About this resource</h2><div class="notes"><p>This curated survey collects publications across research groups. The IC timeline begins with the earliest IC paper currently included, in 2006. Earlier foundational references remain in the bibliography. Counts are publications, not unique chips. The search was refreshed on 13 November 2026; coverage may be incomplete.</p><p><strong>Acknowledgements.</strong> {esc(meta['acknowledgements'])}</p><p><strong>AI usage.</strong> {esc(meta['ai_usage_statement'])}</p><p><strong>Conflict of interest.</strong> {esc(meta['conflict_of_interest_statement'])}</p><p><strong>Inclusion requests.</strong> {esc(meta['inclusion_request'])}</p><p><strong>Corrections.</strong> {esc(meta['corrections'])} <a href="mailto:shreyas@purdue.edu">shreyas@purdue.edu</a></p></div></main>'''
js=r'''
const DATA=JSON.parse(document.getElementById('survey-data').textContent), records=DATA.records;
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=r=>r.doi?'https://doi.org/'+r.doi:r.source;
const safe=u=>/^https?:\/\//.test(u||'')?u:'#';
const ordered=[...records].sort((a,b)=>b.year-a.year||a.id.localeCompare(b.id));let page=0, plotted=[];
[...new Set(records.map(r=>r.year))].sort((a,b)=>b-a).forEach(y=>$('year').add(new Option(y,y)));
[...new Set(records.filter(r=>r.category==='ICs').map(r=>r.mode||'Unclassified'))].sort().forEach(m=>$('plotmode').add(new Option(m,m)));
function renderList(){const q=$('search').value.toLowerCase().trim(), cat=$('category').value, yr=$('year').value;const filtered=ordered.filter(r=>(!cat||r.category===cat)&&(!yr||r.year==yr)&&(!q||[r.id,r.title,r.authors,r.venue,r.venueFull,r.doi,r.mode].join(' ').toLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(filtered.length/50));page=Math.min(page,pages-1);$('resultcount').textContent=`${filtered.length} references · page ${page+1} of ${pages} · 50 per page`;$('pagecount').textContent=filtered.length?`${page*50+1}–${Math.min((page+1)*50,filtered.length)} of ${filtered.length}`:'No matching references';$('prev').disabled=page===0;$('next').disabled=page>=pages-1;$('papers').innerHTML=filtered.slice(page*50,page*50+50).map(r=>`<details class="paper" id="${esc(r.id)}"><summary><span class="ref">[${esc(r.id.split('-')[1])}]</span><span class="paper-title">${esc(r.title)}</span><div class="meta">${esc((r.authors||'').split(';')[0])}${(r.authors||'').includes(';')?' et al.':''} · ${esc(r.venue)} · ${r.year} · ${esc(r.category)}<br><a class="doi" href="${esc(safe(link(r)))}" target="_blank" rel="noopener">${esc(r.doi?'DOI: '+r.doi:'Source')}</a></div></summary><div class="detail"><p>${esc(r.authors)}</p><p>${esc(r.venueFull)} · ${esc(r.mode)}</p><p>${esc(r.notes||'No additional measurement notes recorded.')}</p></div></details>`).join('')||'<p>No references match these filters.</p>';}
['search','category','year'].forEach(id=>$(id).addEventListener('input',()=>{page=0;renderList()}));$('prev').onclick=()=>{page--;renderList()};$('next').onclick=()=>{page++;renderList()};$('toplist').onclick=()=>$('search').scrollIntoView({behavior:'smooth',block:'center'});
function draw(){const key=$('scope').value, mode=$('plotmode').value;plotted=[];records.filter(r=>r.category==='ICs'&&r.chartEligible===true&&(!mode||r.mode===mode)).forEach(r=>(r.points||[]).forEach((p,i)=>{if(Number.isFinite(p[key])&&p[key]>0)plotted.push({r,value:p[key],point:i+1})}));if(!plotted.length){$('plot').innerHTML='<p>No verified numeric energy values for this selection.</p>';return;}const W=1100,H=350,left=78,right=30,top=35,bottom=55,min=Math.floor(Math.log10(Math.min(...plotted.map(p=>p.value)))),max=Math.max(min+1,Math.ceil(Math.log10(Math.max(...plotted.map(p=>p.value))))),X=y=>left+(y-2005.5)/21*(W-left-right),Y=e=>H-bottom-(Math.log10(e)-min)/(max-min)*(H-top-bottom),color={S:'#c52214',T:'#0056b3',U:'#18171c'}[key];let s=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="IC energy per bit versus publication year"><title>IC energy efficiency, 2006 to 2026</title><rect width="${W}" height="${H}" fill="white"/>`;
for(let e=min;e<=max;e++){const y=Y(10**e);s+=`<line x1="${left}" x2="${W-right}" y1="${y}" y2="${y}" stroke="#e2e6ec"/><text x="${left-12}" y="${y+5}" text-anchor="end" font-size="14">${10**e>=10000?'10^'+e:10**e}</text>`;}for(let yr=2006;yr<=2026;yr+=2)s+=`<text x="${X(yr)}" y="${H-bottom+25}" text-anchor="middle" font-size="14">${yr}</text>`;
s+=`<text x="20" y="${H/2}" transform="rotate(-90 20 ${H/2})" text-anchor="middle" font-size="14">Energy (pJ/bit)</text><text x="${W/2}" y="${H-8}" text-anchor="middle" font-size="14">Publication year</text><text x="${W-right}" y="20" text-anchor="end" font-size="13">${plotted.length} operating points / ${new Set(plotted.map(p=>p.r.id)).size} publications</text>`;
plotted.forEach((p,i)=>s+=`<circle cx="${X(p.r.year)}" cy="${Y(p.value)}" r="5" fill="${color}" fill-opacity=".78" stroke="white" stroke-width="1" tabindex="0" role="button" data-point="${i}" aria-label="${esc(p.r.id+' '+p.value+' pJ per bit')}"><title>[${esc(p.r.id.split('-')[1])}] ${esc(p.r.title)}: ${p.value} pJ/bit</title></circle>`);$('plot').innerHTML=s+'</svg>';document.querySelectorAll('[data-point]').forEach(c=>{const show=()=>{const p=plotted[c.dataset.point];$('pick').innerHTML=`<strong>[${esc(p.r.id.split('-')[1])}] ${p.value} pJ/bit · ${esc($('scope').selectedOptions[0].text)}</strong> — <a href="${esc(safe(link(p.r)))}" target="_blank" rel="noopener">${esc(p.r.title)}</a><br>${esc(p.r.notes||'Consult the original publication for measurement conditions.')}`};c.onclick=show;c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show()}}});}
$('scope').onchange=$('plotmode').onchange=()=>{$('pick').textContent='Select a point to inspect its paper and measurement notes.';draw()};
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function csv(rows){return rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
$('csv').onclick=()=>download(csv([['ID','Year','Category','Title','Authors','Venue','DOI','Source','Notes'],...ordered.map(r=>[r.id.split('-')[1],r.year,r.category,r.title,r.authors,r.venueFull,r.doi,link(r),r.notes])]),'HBC_Survey_2026-11-13.csv','text/csv');
$('bib').onclick=()=>download(document.getElementById('bib-data').textContent,'HBC_Survey_2026-11-13.bib','text/plain');
$('plotcsv').onclick=()=>download(csv([['ID','Year','Scope','Energy_pJ_per_bit','Operating_point','DOI','Notes'],...plotted.map(p=>[p.r.id.split('-')[1],p.r.year,$('scope').selectedOptions[0].text,p.value,p.point,p.r.doi,p.r.notes])]),'HBC_IC_energy_2026-11-13.csv','text/csv');
renderList();draw();
'''
# Use ordinary JavaScript slash escapes, not Python double escaping.
js=js.replace(r'/^https?:\\/\\//',r'/^https?:\/\//').replace("join('\\\\r\\\\n')","join('\\r\\n')")
bib=(root/'survey/catalogue.bib').read_text()
page=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(meta["title"])} | SPARC Lab</title>{shared}<link rel="stylesheet" href="static/css/site.css"><style>{css}</style></head><body>{nav}{body}{footer}<script type="application/json" id="survey-data">{json.dumps(d,ensure_ascii=False).replace("</","<\\/")}</script><script type="text/plain" id="bib-data">{bib.replace("</","<\\/")}</script><script>{js}</script></body></html>'
(root/'HBC_Survey.html').write_text(page)
(root/'survey/anc/page.js').write_text(js)
print('Built HTML',len(page))
